# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMB-000001",
    "name": "Priya প্রিয়া",
    "kind": "first-name",
    "meaning": "Priya (প্রিয়া) is a feminine given name in Bengali. Meaning: Beloved. From Sanskrit; common across eastern India."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Pri")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

